  if (is_empty() || (sx==1 && sy==1 && sz==1)) return *this;
  if (sx>1 && _width>1) { // Along X-axis.
    const int L = width(), off = 1, s = (int)sx, _s1 = s/2, _s2 = s - _s1, s1 = _s1>L?L:_s1, s2 = _s2>L?L:_s2;
